// Global procedural labyrinth generator for infinite dynamic play
function generateArrowPuzzle(width, height, targetArrows, minLen = 5, maxLen = 18) {
  const DIRS = [
    { dx: 0, dy: -1, dir: 0 },
    { dx: 1, dy: 0, dir: 1 },
    { dx: 0, dy: 1, dir: 2 },
    { dx: -1, dy: 0, dir: 3 }
  ];

  for (let attempt = 0; attempt < 80; attempt++) {
    const grid = Array.from({ length: height }, () => new Int32Array(width));
    const arrows = [];

    function canRunOut(headX, headY, direction) {
      if (direction === 0) {
        for (let y = headY - 1; y >= 0; y--) if (grid[y][headX] > 0) return false;
        return true;
      }
      if (direction === 1) {
        for (let x = headX + 1; x < width; x++) if (grid[headY][x] > 0) return false;
        return true;
      }
      if (direction === 2) {
        for (let y = headY + 1; y < height; y++) if (grid[y][headX] > 0) return false;
        return true;
      }
      if (direction === 3) {
        for (let x = headX - 1; x >= 0; x--) if (grid[headY][x] > 0) return false;
        return true;
      }
      return false;
    }

    let subAttempts = 0;
    while (arrows.length < targetArrows && subAttempts < 2500) {
      subAttempts++;
      const headX = Math.floor(Math.random() * width);
      const headY = Math.floor(Math.random() * height);
      if (grid[headY][headX] > 0) continue;

      const validDirs = DIRS.filter(d => canRunOut(headX, headY, d.dir));
      if (validDirs.length === 0) continue;
      const chosenDir = validDirs[Math.floor(Math.random() * validDirs.length)];

      const path = [[headX, headY]];
      let curX = headX - chosenDir.dx;
      let curY = headY - chosenDir.dy;

      if (curX < 0 || curX >= width || curY < 0 || curY >= height || grid[curY][curX] > 0) continue;
      path.unshift([curX, curY]);

      const desiredLen = Math.floor(Math.random() * (maxLen - minLen + 1)) + minLen;
      let curDir = chosenDir;
      let straightRun = 1;

      while (path.length < desiredLen) {
        const tail = path[0];
        const possibleSteps = [];

        for (const d of DIRS) {
          if (d.dx === -curDir.dx && d.dy === -curDir.dy) continue;

          const nx = tail[0] - d.dx;
          const ny = tail[1] - d.dy;
          if (nx >= 0 && nx < width && ny >= 0 && ny < height && grid[ny][nx] === 0) {
            if (!path.some(p => p[0] === nx && p[1] === ny)) {
              let inExitRay = false;
              if (chosenDir.dir === 0 && nx === headX && ny < headY) inExitRay = true;
              if (chosenDir.dir === 1 && ny === headY && nx > headX) inExitRay = true;
              if (chosenDir.dir === 2 && nx === headX && ny > headY) inExitRay = true;
              if (chosenDir.dir === 3 && ny === headY && nx < headX) inExitRay = true;

              if (!inExitRay) {
                possibleSteps.push({ x: nx, y: ny, d, isStraight: (d.dir === curDir.dir) });
              }
            }
          }
        }

        if (possibleSteps.length === 0) break;

        const straightStep = possibleSteps.find(s => s.isStraight);
        let nextStep;

        if (straightRun < 2 && straightStep) {
          nextStep = straightStep;
        } else if (straightStep && Math.random() < 0.60) {
          nextStep = straightStep;
        } else {
          const turns = possibleSteps.filter(s => !s.isStraight);
          nextStep = turns.length > 0 ? turns[Math.floor(Math.random() * turns.length)] : straightStep;
        }

        if (!nextStep) break;

        if (nextStep.isStraight) straightRun++;
        else straightRun = 1;

        path.unshift([nextStep.x, nextStep.y]);
        curDir = nextStep.d;
      }

      if (path.length >= Math.max(3, minLen - 1)) {
        const arrowId = arrows.length + 1;
        for (const pt of path) grid[pt[1]][pt[0]] = arrowId;
        arrows.push(path);
      }
    }

    if (arrows.length >= Math.max(4, Math.floor(targetArrows * 0.7))) {
      arrows.reverse();
      const arrowStrings = arrows.map(p => p.map(pt => pt[1] * width + pt[0]).join(','));
      return `${width};${height};${arrowStrings.join('|')}`;
    }
  }
  return null;
}

// Retrieves level for a tier and level number (1-indexed)
function getLevel(tier, levelNum) {
  const tierKey = (tier || 'easy').toLowerCase();
  const list = CURATED_LEVELS[tierKey] || CURATED_LEVELS.easy;
  const index = Math.max(0, (levelNum || 1) - 1);
  if (index < list.length && list[index]) {
    return list[index];
  }

  // If beyond 10, procedurally generate a matching labyrinth level on the fly!
  let width = 16, height = 16, target = 22, minL = 6, maxL = 16;
  if (tierKey === 'easy') { width = 14; height = 14; target = 16; minL = 5; maxL = 14; }
  else if (tierKey === 'medium') { width = 24; height = 24; target = 36; minL = 7; maxL = 20; }
  else if (tierKey === 'hard') { width = 34; height = 34; target = 58; minL = 8; maxL = 24; }
  else if (tierKey === 'complex') { width = 46; height = 46; target = 90; minL = 10; maxL = 28; }

  const generated = generateArrowPuzzle(width, height, target, minL, maxL);
  return generated || list[0];
}

window.CURATED_LEVELS = CURATED_LEVELS;
window.generateArrowPuzzle = generateArrowPuzzle;
window.getLevel = getLevel;
